<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungsanschrift - {{ $kunde->strName }}</title><style>body{font:13px Arial;background:#d9d9d9;padding:12px}.window{max-width:1000px;margin:auto;background:#efefef;border:1px solid #888;padding:14px}.title{color:#0000cc;font-weight:bold;border-bottom:2px solid #0000cc;margin-bottom:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px 22px}.field{display:grid;grid-template-columns:145px 1fr;gap:8px;align-items:center}input{width:100%;padding:6px}.checks{display:flex;gap:20px;margin-top:14px}.actions{display:flex;gap:8px;margin-top:16px}.button,button{padding:7px 12px;border:1px solid #777;background:#eee;color:#111;text-decoration:none}</style></head><body><div class="window"><h2>Rechnungsanschrift</h2><div class="title">{{ $anschrift->exists ? 'Rechnungsanschrift bearbeiten' : 'Neue Rechnungsanschrift' }} für {{ $kunde->strName }}</div><form method="POST" action="{{ $anschrift->exists ? route('kunden.rechnungsanschriften.update',[$kunde->intID,$anschrift->intID]) : route('kunden.rechnungsanschriften.store',$kunde->intID) }}">@csrf @if($anschrift->exists) @method('PUT') @endif<div class="grid">@foreach(['strName'=>'Name','strZuHaenden'=>'Zu Händen','strStrasse'=>'Straße','strPLZ'=>'PLZ','strOrt'=>'Ort','strEmail'=>'E-Mail','strUStIdNr'=>'USt-IdNr.','strKundenreferenz'=>'Kundenreferenz','strInhaber'=>'Kontoinhaber','strIBAN'=>'IBAN','strBIC'=>'BIC','strKontoNr'=>'Kontonummer','strBLZ'=>'BLZ','strInstitut'=>'Institut','strLieferantenId'=>'Lieferanten-ID','strLeitwegId'=>'Leitweg-ID'] as $name=>$label)<div class="field"><label>{{ $label }}</label><input name="{{ $name }}" value="{{ old($name,$anschrift->$name) }}" @if($name==='strName') required @endif></div>@endforeach</div><div class="checks"><label><input style="width:auto" type="checkbox" name="boolSEPA" value="1" @checked(old('boolSEPA',$anschrift->boolSEPA))> SEPA</label><label><input style="width:auto" type="checkbox" name="boolErstlastschrift" value="1" @checked(old('boolErstlastschrift',$anschrift->boolErstlastschrift))> Erstlastschrift</label><label><input style="width:auto" type="checkbox" name="boolXRechnung" value="1" @checked(old('boolXRechnung',$anschrift->boolXRechnung))> XRechnung</label></div><div class="actions"><button type="submit">Speichern</button><a class="button" href="{{ route('kunden.rechnungsanschriften.index',$kunde->intID) }}">Abbrechen</a></div></form></div><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>